insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g7_science_v1'
from (values
('112.27.b.6.A',2,'A substance made of only one kind of atom is called a(n)...','["element", "mixture", "compound", "solution"]'::jsonb,0,'Elements contain just one type of atom.','original'),
('112.27.b.6.A',3,'Water (H2O) is made of hydrogen and oxygen atoms chemically bonded. Water is a...','["metal", "compound", "element", "mixture of elements"]'::jsonb,1,'Two or more elements bonded in a fixed ratio form a compound.','original'),
('112.27.b.6.A',3,'Which is the chemical symbol for sodium?','["So", "N", "Na", "S"]'::jsonb,2,'Sodium comes from the Latin natrium, symbol Na.','original'),
('112.27.b.6.A',3,'What does the chemical formula CO2 tell you?','["it has two carbon atoms and one oxygen atom", "it has three carbon atoms", "it is an element", "each molecule has one carbon atom and two oxygen atoms"]'::jsonb,3,'The subscript 2 applies to the oxygen only.','original'),
('112.27.b.6.A',4,'How is an element different from a compound?','["a compound is made of two or more kinds of atoms bonded together", "an element can be broken down by chemical changes into simpler elements", "a compound has only one kind of atom", "an element is always a gas"]'::jsonb,0,'Compounds combine different elements; elements cannot be broken down chemically.','original'),
('112.27.b.6.A',4,'Which of these is a molecule of an element?','["H2O", "O2", "CO2", "NaCl"]'::jsonb,1,'O2 has two atoms but both are oxygen.','original'),
('112.27.b.6.A',4,'Which pair contains one element and one compound?','["water (H2O) and carbon dioxide (CO2)", "gold (Au) and silver (Ag)", "iron (Fe) and table salt (NaCl)", "helium (He) and neon (Ne)"]'::jsonb,2,'Fe is an element; NaCl is a compound.','original'),
('112.27.b.6.B',3,'How many atoms are in one molecule of H2O?','["1", "4", "2", "3"]'::jsonb,3,'Two hydrogen atoms plus one oxygen atom make three atoms.','original'),
('112.27.b.6.B',3,'How many hydrogen atoms are in one molecule of CH4?','["4", "1", "2", "5"]'::jsonb,0,'The subscript 4 follows the H.','original'),
('112.27.b.6.B',3,'Which elements are in the compound NaCl?','["sodium and carbon", "sodium and chlorine", "sulfur and chlorine", "nitrogen and carbon"]'::jsonb,1,'Na is sodium and Cl is chlorine.','original'),
('112.27.b.6.B',4,'How many total atoms are in one molecule of C6H12O6?','["6", "12", "24", "18"]'::jsonb,2,'6 + 12 + 6 = 24 atoms.','original'),
('112.27.b.6.B',4,'In the formula H2SO4, how many oxygen atoms are there?','["6", "1", "2", "4"]'::jsonb,3,'The subscript after O is 4.','original'),
('112.27.b.6.B',4,'A formula contains the symbols C, H and O. Which tool lets you find each element''s name and atomic number?','["the periodic table", "a graduated cylinder", "a thermometer", "a ruler"]'::jsonb,0,'The periodic table lists every element with its symbol and atomic number.','original'),
('112.27.b.6.B',4,'In Ca(OH)2, how many hydrogen atoms are there?','["4", "2", "1", "3"]'::jsonb,1,'The 2 outside the parentheses multiplies both O and H, giving 2 H.','original'),
('112.27.b.6.C',2,'Which is a physical change?','["iron rusting", "wood burning", "ice melting", "milk souring"]'::jsonb,2,'Melting changes state but not the substance.','original'),
('112.27.b.6.C',3,'Which is a chemical change?','["water freezing", "paper being cut", "sugar dissolving in tea", "a nail rusting"]'::jsonb,3,'Rust is a new substance.','original'),
('112.27.b.6.C',3,'Which observation is a sign of a chemical change?','["bubbles of gas form and a new smell appears", "a metal is bent", "a liquid is poured into a new container", "a solid is broken into smaller pieces"]'::jsonb,0,'New gas and odor indicate new substances.','original'),
('112.27.b.6.C',3,'Crushing a can is a...','["nuclear change", "physical change", "decomposition", "chemical change"]'::jsonb,1,'The can is the same material, only its shape changed.','original'),
('112.27.b.6.C',4,'Baking a cake batter turns it into a solid cake that cannot go back to batter. This is a...','["dissolving", "physical change", "chemical change", "state change only"]'::jsonb,2,'New substances form that cannot be reversed easily.','original'),
('112.27.b.6.C',4,'A student heats sugar and it turns black and smells burnt. What kind of change occurred?','["physical change", "no change", "change in state only", "chemical change"]'::jsonb,3,'Color change and odor show new substances formed.','original'),
('112.27.b.6.C',4,'Which pair lists one physical and one chemical change?','["boiling water; burning a candle", "rusting a bike; baking bread", "tearing paper; folding paper", "melting butter; freezing juice"]'::jsonb,0,'Boiling is physical, burning is chemical.','original'),
('112.27.b.6.D',2,'In salt water, the salt is the...','["solution", "solute", "compound only", "solvent"]'::jsonb,1,'The solute is what gets dissolved.','original'),
('112.27.b.6.D',2,'In salt water, the water is the...','["solute", "precipitate", "solvent", "mixture"]'::jsonb,2,'The solvent does the dissolving.','original'),
('112.27.b.6.D',3,'A student dissolves 5 g of sugar in 100 mL of water and another student dissolves 20 g in 100 mL. Which solution is more concentrated?','["the 5 g solution", "they are equal", "neither is a solution", "the 20 g solution"]'::jsonb,3,'More solute in the same volume means higher concentration.','original'),
('112.27.b.6.D',3,'What happens to concentration when you add more water to a solution?','["it decreases", "it increases", "it becomes zero immediately", "it stays the same"]'::jsonb,0,'Diluting spreads the solute through more solvent.','original'),
('112.27.b.6.D',4,'A drink mix is too strong. Which action dilutes it?','["freezing it", "adding more water", "adding more mix", "boiling off water"]'::jsonb,1,'Dilution adds solvent.','original'),
('112.27.b.6.D',4,'A solution in which water is the solvent is called...','["an alloy", "a suspension", "an aqueous solution", "a gas solution"]'::jsonb,2,'Aqueous means water-based.','original'),
('112.27.b.6.D',4,'One cup of lemonade has 2 spoons of sugar. Another cup of the same size has 4 spoons. What is true?','["the second cup has less solute", "the cups have equal concentration", "the first cup has a higher concentration", "the second cup has a higher concentration of sugar"]'::jsonb,3,'More solute per volume is more concentrated.','original'),
('112.27.b.6.E',3,'Which change makes sugar dissolve faster in water?','["stirring it", "leaving it still", "using colder water", "using one big lump"]'::jsonb,0,'Agitation brings fresh solvent to the solute.','original'),
('112.27.b.6.E',3,'A student dissolves sugar in water at three different temperatures. Which dissolves it fastest?','["none of them", "the warmest sample", "the same in all three", "the coldest sample"]'::jsonb,1,'Faster-moving particles speed up dissolving.','original'),
('112.27.b.6.E',3,'Which dissolves fastest in water?','["a sugar cube", "a large sugar lump", "powdered sugar", "rock candy"]'::jsonb,2,'Smaller pieces expose more surface area.','original'),
('112.27.b.6.E',4,'A student tests how temperature affects dissolving rate. Which variable should stay the same?','["the result", "the water temperature", "the dissolving time", "the amount of sugar and water"]'::jsonb,3,'Only temperature should change.','original'),
('112.27.b.6.E',4,'Crushing a tablet before putting it in water makes it dissolve faster because the crushed pieces have more...','["surface area exposed to the water", "volume of water", "mass", "weight"]'::jsonb,0,'More exposed surface means more contact with solvent.','original'),
('112.27.b.6.E',4,'Which combination would dissolve a solid the fastest?','["cold water, no stirring and a large chunk", "warm water, stirring and crushed pieces", "cold water, stirring and a large chunk", "warm water, no stirring and a large chunk"]'::jsonb,1,'All three factors speed dissolving.','original'),
('112.27.b.6.E',4,'Two cups of the same temperature water get the same amount of salt. One is stirred, one is not. What is the stirred cup showing?','["salt is not soluble", "surface area has no effect", "agitation increases the rate of dissolving", "temperature affects solubility"]'::jsonb,2,'Stirring was the only difference.','original'),
('112.27.b.7.A',2,'What is the formula for average speed?','["time divided by distance", "mass divided by volume", "distance times time", "distance divided by time"]'::jsonb,3,'Speed = distance / time.','original'),
('112.27.b.7.A',3,'A cyclist rides 30 km in 2 hours. What is the average speed?','["15 km/h", "60 km/h", "28 km/h", "32 km/h"]'::jsonb,0,'30 / 2 = 15.','original'),
('112.27.b.7.A',3,'A runner travels 100 m in 20 seconds. What is the average speed?','["2000 m/s", "5 m/s", "20 m/s", "0.2 m/s"]'::jsonb,1,'100 / 20 = 5.','original'),
('112.27.b.7.A',3,'A car goes 240 km at 60 km/h. How long does the trip take?','["14,400 hours", "0.25 hours", "4 hours", "300 hours"]'::jsonb,2,'Time = distance / speed = 240 / 60.','original'),
('112.27.b.7.A',4,'A train travels 90 km in 1.5 hours. What is its average speed?','["90 km/h", "135 km/h", "6 km/h", "60 km/h"]'::jsonb,3,'90 / 1.5 = 60.','original'),
('112.27.b.7.A',4,'A student walks 400 m in 5 minutes. What distance does the student walk in 1 minute at the same speed?','["80 m", "405 m", "2000 m", "395 m"]'::jsonb,0,'400 / 5 = 80.','original'),
('112.27.b.7.A',4,'A boat moves at 12 km/h for 3 hours. How far does it travel?','["9 km", "36 km", "4 km", "15 km"]'::jsonb,1,'Distance = speed x time.','original'),
('112.27.b.7.B',3,'Which statement describes velocity?','["distance only", "acceleration only", "speed in a given direction", "speed without direction"]'::jsonb,2,'Velocity includes direction.','original'),
('112.27.b.7.B',3,'A car travels 50 km/h north. This describes the car''s...','["mass", "displacement only", "speed only", "velocity"]'::jsonb,3,'A direction is included.','original'),
('112.27.b.7.B',4,'A runner jogs once around a 400 m track and returns to the starting point. What is her displacement?','["0 m", "400 m", "200 m", "800 m"]'::jsonb,0,'Displacement is the straight-line change in position, which is zero.','original'),
('112.27.b.7.B',4,'A person walks 3 m east and then 3 m west. How far did the person travel (distance)?','["3 m", "6 m", "9 m", "0 m"]'::jsonb,1,'Distance adds the path lengths.','original'),
('112.27.b.7.B',4,'A person walks 3 m east and then 3 m west. What is the displacement?','["3 m east", "6 m", "0 m", "3 m west"]'::jsonb,2,'The person ends where they started.','original'),
('112.27.b.7.B',4,'Two cars both go 60 km/h, one east and one west. What is true?','["they have the same velocity", "they have different speeds", "they are not moving", "they have the same speed but different velocities"]'::jsonb,3,'Direction differs.','original'),
('112.27.b.7.B',3,'Which measurement needs a direction to be complete?','["displacement", "distance", "time", "speed"]'::jsonb,0,'Displacement is a vector.','original'),
('112.27.b.7.C',2,'On a distance-time graph, a horizontal line means the object is...','["moving backward", "not moving", "speeding up", "moving at constant speed"]'::jsonb,1,'Distance is not changing.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
