from (values
('112.27.b.7.C',3,'On a distance-time graph, a straight line sloping upward means the object moves at...','["no speed", "constant acceleration", "constant speed", "decreasing speed"]'::jsonb,2,'Equal distance in equal time.','original'),
('112.27.b.7.C',3,'A steeper line on a distance-time graph shows a...','["smaller distance", "stopped object", "slower speed", "faster speed"]'::jsonb,3,'A greater slope is more speed.','original'),
('112.27.b.7.C',4,'A graph shows 0 m at 0 s and 20 m at 4 s as a straight line. What is the speed?','["5 m/s", "24 m/s", "80 m/s", "0.2 m/s"]'::jsonb,0,'20 / 4 = 5.','original'),
('112.27.b.7.C',4,'A distance-time graph rises, then goes flat, then rises again. What happened?','["the object slowed to a stop for good", "the object moved, stopped, then moved again", "the object moved backward", "the object kept the same speed throughout"]'::jsonb,1,'The flat part means no change in distance.','original'),
('112.27.b.7.C',4,'The slope of a distance-time graph represents the object''s...','["mass", "weight", "speed", "energy"]'::jsonb,2,'Slope = rise / run = distance / time.','original'),
('112.27.b.7.C',4,'Two lines on one graph: Line A is steeper than Line B. Which object is faster?','["they are equal", "neither", "Object B", "Object A"]'::jsonb,3,'A steeper line means more distance per second.','original'),
('112.27.b.7.D',2,'Newton''s First Law says an object at rest stays at rest unless acted on by a(n)...','["unbalanced force", "small force", "magnet", "balanced force"]'::jsonb,0,'A net force is needed to change motion.','original'),
('112.27.b.7.D',3,'Balanced forces on an object cause the object''s motion to...','["speed up", "stay the same", "reverse", "stop immediately"]'::jsonb,1,'Net force is zero.','original'),
('112.27.b.7.D',3,'A book sits on a table. Gravity pulls down and the table pushes up equally. The forces are...','["unbalanced", "absent", "balanced", "friction only"]'::jsonb,2,'Equal and opposite forces cancel.','original'),
('112.27.b.7.D',3,'A hockey puck slides on ice, slowly stopping. What unbalanced force slows it?','["no force", "balanced forces", "gravity pulling sideways", "friction"]'::jsonb,3,'Friction opposes sliding.','original'),
('112.27.b.7.D',4,'Why do passengers lurch forward when a car brakes suddenly?','["their bodies tend to keep moving at the same speed", "the car pulls them", "the seat pushes them forward", "gravity pulls them forward"]'::jsonb,0,'Inertia keeps them moving.','original'),
('112.27.b.7.D',4,'A cart is pushed with 10 N to the right and 10 N to the left. What happens?','["it spins", "the cart does not change its motion", "it speeds up left", "it speeds up right"]'::jsonb,1,'Net force is 0 N.','original'),
('112.27.b.7.D',4,'A cart is pushed with 15 N to the right and 5 N to the left. What is the net force?','["20 N to the right", "10 N to the left", "10 N to the right", "0 N"]'::jsonb,2,'15 - 5 = 10 in the larger direction.','original'),
('112.27.b.8.A',2,'Heat transfer through direct contact between objects is called...','["reflection", "convection", "radiation", "conduction"]'::jsonb,3,'Particles collide and pass energy along.','original'),
('112.27.b.8.A',3,'Heat transfer by the movement of fluids such as air or water is called...','["convection", "radiation", "conduction", "friction"]'::jsonb,0,'Warm fluid rises while cooler fluid sinks.','original'),
('112.27.b.8.A',3,'Heat from the Sun reaches Earth by...','["friction", "radiation", "convection", "conduction"]'::jsonb,1,'Radiation can travel through empty space.','original'),
('112.27.b.8.A',3,'A metal spoon in hot soup becomes hot. This is mainly...','["convection", "radiation", "conduction", "evaporation"]'::jsonb,2,'The spoon touches the hot soup.','original'),
('112.27.b.8.A',4,'Warming your hands near a campfire without touching it is mostly...','["conduction", "condensation", "convection", "radiation"]'::jsonb,3,'Energy travels as waves.','original'),
('112.27.b.8.A',4,'A pot of water is heated from below. Warm water rises and cool water sinks. This circulation is...','["a convection current", "radiation", "a conduction current", "a density wave"]'::jsonb,0,'Fluids move in loops when heated.','original'),
('112.27.b.8.A',4,'Why are cooking pots often made of metal?','["metals never get hot", "metals conduct thermal energy well", "metals radiate energy only", "metals are convection fluids"]'::jsonb,1,'Good conductors transfer energy quickly.','original'),
('112.27.b.8.B',2,'Thermal energy naturally moves from...','["nowhere", "equal temperatures only", "warmer objects to cooler objects", "cooler to warmer objects"]'::jsonb,2,'Energy flows down the temperature difference.','original'),
('112.27.b.8.B',3,'A hot cup of cocoa is left on a table. What happens to its temperature?','["it stays hot forever", "it increases", "it drops below room temperature", "it decreases until it matches the room"]'::jsonb,3,'It reaches thermal equilibrium with its surroundings.','original'),
('112.27.b.8.B',3,'An ice cube is dropped in a glass of warm water. Which way does thermal energy move?','["from the water to the ice", "neither way", "out of the glass only", "from the ice to the water"]'::jsonb,0,'Warm water is the energy source.','original'),
('112.27.b.8.B',3,'Thermal equilibrium means two objects in contact have the same...','["volume", "temperature", "color", "mass"]'::jsonb,1,'No net energy flows once temperatures are equal.','original'),
('112.27.b.8.B',4,'A hot piece of metal at 90 C is placed in 20 C water. The final temperature of both will be...','["above 90 C", "exactly 90 C", "between 20 C and 90 C", "below 20 C"]'::jsonb,2,'They meet at an in-between temperature.','original'),
('112.27.b.8.B',4,'Once two objects reach thermal equilibrium, thermal energy...','["flows faster", "stops existing", "moves toward the colder one", "has no net flow between them"]'::jsonb,3,'Energy transfer balances out.','original'),
('112.27.b.8.B',4,'A can of soda is placed in a cooler of ice. Which is a correct prediction?','["the soda cools as it gives energy to the ice", "the ice warms because it gains cold", "the ice cools the soda by taking cold from it", "the soda warms the ice and stays the same"]'::jsonb,0,'Energy leaves the warmer soda.','original'),
('112.27.b.8.C',2,'Temperature measures the average...','["volume of the sample", "kinetic energy of the particles", "color of the substance", "mass of the particles"]'::jsonb,1,'Hotter means faster-moving particles.','original'),
('112.27.b.8.C',3,'When the temperature of a gas rises, its particles...','["move slower", "disappear", "move faster", "stop moving"]'::jsonb,2,'Higher temperature means more kinetic energy.','original'),
('112.27.b.8.C',3,'Particles in a cold liquid compared with a warm liquid move...','["at the same speed", "in straight lines only", "more quickly", "more slowly"]'::jsonb,3,'Less kinetic energy at lower temperature.','original'),
('112.27.b.8.C',3,'As a solid is heated, its particles...','["vibrate faster", "stay perfectly still", "turn into energy", "stop vibrating"]'::jsonb,0,'Energy increases the vibration.','original'),
('112.27.b.8.C',4,'Which sample has the highest average particle kinetic energy?','["water at 40 C", "water at 80 C", "water at 0 C", "water at 10 C"]'::jsonb,1,'The warmest sample has the fastest particles.','original'),
('112.27.b.8.C',4,'Absolute zero is the temperature at which particle motion is...','["at a maximum", "random", "at a minimum", "doubled"]'::jsonb,2,'Particles have almost no kinetic energy.','original'),
('112.27.b.8.C',4,'Two beakers hold equal masses of water: one at 25 C and one at 75 C. Which statement is correct?','["particles in the 75 C beaker are larger", "the particles in the 25 C beaker move faster", "particles in both move at the same speed", "the particles in the 75 C beaker move faster on average"]'::jsonb,3,'Higher temperature, faster particles.','original'),
('112.27.b.9.A',2,'What is at the center of our solar system?','["the Sun", "Jupiter", "the Moon", "Earth"]'::jsonb,0,'All planets orbit the Sun.','original'),
('112.27.b.9.A',3,'Which is the largest planet in our solar system?','["Earth", "Jupiter", "Neptune", "Mars"]'::jsonb,1,'Jupiter is the largest of all.','original'),
('112.27.b.9.A',3,'Where is the asteroid belt located?','["around the Sun only", "between Earth and Venus", "between Mars and Jupiter", "beyond Neptune"]'::jsonb,2,'Rocky bodies orbit in that region.','original'),
('112.27.b.9.A',3,'A comet gets a visible tail when it approaches the Sun because...','["it spins faster", "its rocks melt", "it gets magnetized", "ices vaporize and are pushed away by the solar wind"]'::jsonb,3,'Heat releases gas and dust.','original'),
('112.27.b.9.A',4,'Which region is a band of icy objects beyond Neptune?','["the Kuiper belt", "the Oort cloud", "the inner planets", "the asteroid belt"]'::jsonb,0,'The Kuiper belt includes Pluto-like icy bodies.','original'),
('112.27.b.9.A',4,'The Oort cloud is thought to be...','["a cloud of gas near Earth", "a distant spherical shell of icy objects surrounding the solar system", "a belt between Mars and Jupiter", "a ring around Saturn"]'::jsonb,1,'It is the source of some long-period comets.','original'),
('112.27.b.9.A',4,'A meteor is...','["a rock on Earth''s surface", "a moon of Jupiter", "the streak of light from a space rock burning up in Earth''s atmosphere", "a planet"]'::jsonb,2,'Friction with air makes it glow.','original'),
('112.27.b.9.B',2,'What force keeps planets in orbit around the Sun?','["wind", "friction", "magnetism", "gravity"]'::jsonb,3,'The Sun''s gravity pulls the planets.','original'),
('112.27.b.9.B',3,'Gravity between two objects depends on their...','["masses and the distance between them", "colors", "ages", "temperatures"]'::jsonb,0,'More mass or less distance means stronger gravity.','original'),
('112.27.b.9.B',3,'What keeps the Moon in orbit around Earth?','["the Sun''s magnetism", "Earth''s gravity", "friction", "solar wind"]'::jsonb,1,'Gravity continually pulls the Moon toward Earth.','original'),
('112.27.b.9.B',4,'As the distance between two objects increases, the gravitational force between them...','["doubles", "stays the same", "decreases", "increases"]'::jsonb,2,'Gravity weakens with distance.','original'),
('112.27.b.9.B',4,'Why do planets closer to the Sun orbit faster?','["they are lighter", "there is no gravity far away", "they are made of denser rock", "the Sun''s gravity is stronger at shorter distances"]'::jsonb,3,'Stronger pull requires faster motion to stay in orbit.','original'),
('112.27.b.9.B',4,'Which object has the strongest gravitational pull on Earth?','["the Sun", "the Moon", "Mars", "Jupiter"]'::jsonb,0,'Its huge mass keeps Earth in orbit even at a great distance.','original'),
('112.27.b.9.B',4,'If Earth''s gravity suddenly vanished, what would happen to the Moon?','["it would keep orbiting", "it would travel in a straight line away", "it would stop", "it would crash into Earth"]'::jsonb,1,'Without a centripetal pull, inertia carries it straight.','original'),
('112.27.b.9.C',2,'Which is needed for life as we know it?','["extreme heat", "complete darkness", "liquid water", "no atmosphere"]'::jsonb,2,'Life needs liquid water.','original'),
('112.27.b.9.C',3,'Earth''s distance from the Sun is important for life because it...','["stops all radiation", "keeps it frozen", "makes Earth the largest planet", "allows liquid water to exist"]'::jsonb,3,'Not too hot and not too cold.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
